export const TrackingSystem = {
  GITHUB_ISSUE: 'github_issue',
  OTHER: 'other',
} as const

export type TrackingSystem = (typeof TrackingSystem)[keyof typeof TrackingSystem]

export type TrackingIssue = {
  id: number // database ID
  nodeId: string // GraphQL ID, needed for the RepositoryAndIssuePicker
  number: number
  repository: {
    ownerLogin: string
    name: string
    typeIcon: string
    defaultBranch: string
  }
  state: string
  stateReason: string | null
  title: string
  titleHTML: string
  url: string
}

export type TrackingLink = {
  trackingSystem: TrackingSystem
  issue: TrackingIssue | null
  trackingUrl: string | null
}
