import {AlertMetadata} from '@github-ui/platform-patterns/AlertPageSidebar'
import {Label, LabelGroup, Link, Stack} from '@primer/react'

import type {RuntimeRisk} from '../types/runtime-risk'

interface RuntimeRisksProps {
  risks?: RuntimeRisk[]
}

export function RuntimeRisks({risks}: RuntimeRisksProps) {
  if (!risks || risks.length === 0) return null

  return (
    <AlertMetadata
      title="Runtime risks"
      variant="info"
      infoContent={
        <Stack gap="condensed" padding="normal" align="start">
          <span>
            Active deployment records impacted by this vulnerability have been detected and tagged with runtime risks.
          </span>
          <Link href="https://docs.github.com/en/code-security/how-tos/manage-security-alerts/remediate-alerts-at-scale/filtering-alerts-in-security-overview#production-context-filters">
            Learn more about runtime risks
          </Link>
        </Stack>
      }
    >
      <LabelGroup>
        {risks.map(risk => (
          <Label key={risk} variant="secondary">
            {risk}
          </Label>
        ))}
      </LabelGroup>
    </AlertMetadata>
  )
}
