import {Button} from '@primer/react'

import {
  CodeScanningCreateBranchDialog,
  type CodeScanningCreateBranchDialogProps,
} from '@github-ui/code-scanning-shared/components/CodeScanningCreateBranchDialog'
import {useRef, useState} from 'react'

type CreateBranchLinkProps = Pick<
  CodeScanningCreateBranchDialogProps,
  'alertNumbers' | 'alertNumbersWithSuggestedFixes' | 'createPath' | 'repository' | 'branchListCacheKey'
> & {
  alertTitle: string
  onBranchCreated: (branchName: string) => void
}

export function DevelopmentSectionCreateBranchLink(props: CreateBranchLinkProps) {
  const {
    alertNumbers,
    alertNumbersWithSuggestedFixes,
    createPath,
    repository,
    branchListCacheKey,
    alertTitle,
    onBranchCreated,
  } = props
  const [showCreateBranchDialog, setShowCreateBranchDialog] = useState(false)
  const pendingBranchNameRef = useRef<string | null>(null)

  const openCreateBranchDialog = () => {
    setShowCreateBranchDialog(true)
  }

  const handleCreateBranchDialogClose = () => {
    setShowCreateBranchDialog(false)
    // Update the branch list after the dialog fully closes
    if (pendingBranchNameRef.current) {
      onBranchCreated(pendingBranchNameRef.current)
      pendingBranchNameRef.current = null
    }
  }

  const handleBranchCreated = (
    nextStep: string,
    branchName: string | null,
    _pullRequest: unknown,
    _errorMessages?: string[],
  ) => {
    if (!branchName) return

    // If navigating to a PR, update immediately
    if (nextStep === 'pr') {
      onBranchCreated(branchName)
    } else {
      // For 'local' and 'desktop' next steps, store the branch name and update when dialog closes
      pendingBranchNameRef.current = branchName
    }
  }

  return (
    <>
      {alertNumbersWithSuggestedFixes.length > 0 ? (
        <>
          <Button
            variant="link"
            aria-label="Commit Copilot Autofix to a new branch"
            onClick={openCreateBranchDialog}
            data-testid="development-section-commit-autofix-button"
          >
            Commit Copilot Autofix to a new branch
          </Button>{' '}
          or link a branch or pull request to address this alert.
        </>
      ) : (
        <>
          Link a branch, pull request, or{' '}
          <Button
            variant="link"
            aria-label="Create a new branch"
            onClick={openCreateBranchDialog}
            data-testid="development-section-create-branch-button"
          >
            create a new branch
          </Button>{' '}
          to start working on this alert.
        </>
      )}

      {showCreateBranchDialog && (
        <CodeScanningCreateBranchDialog
          alertNumbers={alertNumbers}
          alertNumbersWithSuggestedFixes={alertNumbersWithSuggestedFixes}
          createPath={createPath}
          repository={repository}
          branchListCacheKey={branchListCacheKey}
          firstAlertWithSuggestedFixTitle={alertTitle}
          onClose={handleCreateBranchDialogClose}
          onSuccess={handleBranchCreated}
          branchType="new"
          isCampaign={false}
          someSelectedAlertsAreClosed={false}
        />
      )}
    </>
  )
}
