import {ActionList} from '@primer/react'
import type {Repository} from '../types/repository'
import type {SecurityCampaign} from '../types/security-campaign'
import {SecurityCampaignItem} from './SecurityCampaignItem'

export type SecurityCampaignsProps = {
  securityCampaigns: SecurityCampaign[]
  repository: Repository
}

export function SecurityCampaigns({securityCampaigns, repository}: SecurityCampaignsProps) {
  if (securityCampaigns.length === 0) {
    return <span>No campaign is currently tracking this alert.</span>
  }

  return (
    <ActionList variant="full">
      {securityCampaigns.map(campaign => (
        <SecurityCampaignItem key={campaign.number} securityCampaign={campaign} repository={repository} />
      ))}
    </ActionList>
  )
}
