import {useCallback, useState} from 'react'
import {useAlive} from '@github-ui/use-alive'
import {AssigneesSection} from '@github-ui/security-products-alert-assignees/components/AssigneesSection'
import type {Assignee, CodeScanningAssigneesRepository} from './types'
import {codeScanningAlertAssigneesPath, codeScanningAvailableAssigneesPath} from '@github-ui/paths'
import {dispatchAgenticAutofixError, dispatchAgenticAutofixStarted} from './agentic-autofix-event'
import {
  AgenticAutofixError,
  createAgenticAutofixErrorFromResponse,
} from '@github-ui/code-scanning-shared/types/agentic-autofix-error'
import {
  UpdateAlertAssigneesError,
  type UpdateAlertAssigneesResponse,
} from '@github-ui/security-products-alert-assignees/types'
import {displayFlashMessage} from '@github-ui/security-products-alert-assignees/flash-message'

export interface CodeScanningAssigneesSectionProps {
  alertNumber: number
  repository: CodeScanningAssigneesRepository
  currentUser: Assignee
  copilotBot: Assignee | null
  assignees: Assignee[]
  readonly: boolean
  assignableToCopilot?: boolean
  hasValidSuggestedFix?: boolean
  suggestedFixAliveChannel?: string
  useAgenticAutofix?: boolean
}

/** Triggers a re-fetch of the suggested fix banner partial */
async function refreshSuggestedFixBanner() {
  // Only run in browser environment
  if (typeof window === 'undefined') return

  // updateContent requires the data-url attribute to be present
  const bannerElement = document.querySelector<HTMLElement>('.js-suggested-fix-partial[data-url]')
  if (bannerElement) {
    // Dynamic import to avoid SSR issues - the module may reference `window` at initialization
    // This avoids a "ReferenceError: window is not defined" error from the Alloy smoke test
    const {updateContent} = await import('@github-ui/updatable-content')
    updateContent(bannerElement)
  }
}

export type UpdateCodeScanningAlertAssigneesResponse = UpdateAlertAssigneesResponse & {
  agenticAutofixJobId?: string | null
}

export function CodeScanningAssigneesSection({
  alertNumber,
  repository,
  currentUser,
  copilotBot,
  assignees,
  readonly,
  assignableToCopilot,
  hasValidSuggestedFix: initialHasValidSuggestedFix,
  suggestedFixAliveChannel,
  useAgenticAutofix,
}: CodeScanningAssigneesSectionProps) {
  const [hasValidSuggestedFix, setHasValidSuggestedFix] = useState(initialHasValidSuggestedFix)

  useAlive<{has_valid_suggested_fix?: boolean}>(
    suggestedFixAliveChannel,
    useCallback((data: {has_valid_suggested_fix?: boolean}) => {
      if (data.has_valid_suggested_fix !== undefined) {
        setHasValidSuggestedFix(data.has_valid_suggested_fix)
      }
    }, []),
  )

  const handleCopilotAgenticAssignment = (data: UpdateCodeScanningAlertAssigneesResponse | null) => {
    refreshSuggestedFixBanner()
    if (data?.agenticAutofixJobId) {
      dispatchAgenticAutofixStarted({
        jobId: data.agenticAutofixJobId,
      })
    }
  }

  const handleOnAssignError = async (error: Error) => {
    if (error instanceof UpdateAlertAssigneesError) {
      // This is the generic error thrown by the mutation when the response is not ok. We want to check if it's an
      // agentic autofix error and convert it to that error type instead.
      const agenticAutofixError = await createAgenticAutofixErrorFromResponse(error.response)
      if (agenticAutofixError) {
        error = agenticAutofixError
      }
    }

    if (error instanceof AgenticAutofixError) {
      // The error will be shown in the agentic autofix banner rather than as a flash message
      dispatchAgenticAutofixError(error)
    } else {
      displayFlashMessage('Unable to save your selection due to server error. Try again later.', 'error')
    }
  }

  return (
    <AssigneesSection<UpdateCodeScanningAlertAssigneesResponse>
      availableAssigneesPath={codeScanningAvailableAssigneesPath({owner: repository.ownerLogin, repo: repository.name})}
      updateAssigneesPath={codeScanningAlertAssigneesPath({
        owner: repository.ownerLogin,
        repo: repository.name,
        alertNumber,
      })}
      currentUser={currentUser}
      assignees={assignees}
      readonly={readonly}
      // When using agentic autofix, we don't need to check if the suggested
      // fix is already generated.
      assignableToCopilot={assignableToCopilot && (useAgenticAutofix || hasValidSuggestedFix)}
      useAgenticAutofix={useAgenticAutofix}
      showAssignToAgentButton={!!copilotBot}
      onCopilotAgenticAssignment={handleCopilotAgenticAssignment}
      assignToAgentAssignee={copilotBot}
      onAssignError={handleOnAssignError}
    />
  )
}
