import {
  GitMergeIcon,
  GitPullRequestClosedIcon,
  GitPullRequestDraftIcon,
  GitPullRequestIcon,
} from '@primer/octicons-react'
import {ActionList, BranchName, RelativeTime, Text} from '@primer/react'

import type {PullRequestData} from '../types'

function PullRequestDescription({state, number, createdAt, baseRefName, closedAt, mergedAt}: PullRequestData) {
  switch (state) {
    case 'OPEN':
    case 'DRAFT':
      return (
        <>
          #{number} opened <RelativeTime datetime={createdAt} tense="past" /> merges into{' '}
          <BranchName as="span">{baseRefName}</BranchName>
        </>
      )
    case 'CLOSED':
      return (
        <>
          #{number} was closed {closedAt && <RelativeTime datetime={closedAt} tense="past" />}
        </>
      )
    case 'MERGED':
      return (
        <>
          #{number} was merged into <BranchName as="span">{baseRefName}</BranchName>{' '}
          {mergedAt && <RelativeTime datetime={mergedAt} tense="past" />}
        </>
      )
    default:
      return null
  }
}

export function PullRequestItem({pr}: {pr: PullRequestData}) {
  const {title, url, state} = pr

  const getIcon = () => {
    switch (state) {
      case 'OPEN':
        return <GitPullRequestIcon className="fgColor-open" />
      case 'CLOSED':
        return <GitPullRequestClosedIcon className="fgColor-closed" />
      case 'MERGED':
        return <GitMergeIcon className="fgColor-done" />
      case 'DRAFT':
        return <GitPullRequestDraftIcon />
    }
  }

  return (
    <ActionList.LinkItem href={url} target="_blank" data-testid="development-section-pull-request-item">
      <ActionList.LeadingVisual>{getIcon()}</ActionList.LeadingVisual>

      <Text weight="normal">{title}</Text>

      <ActionList.Description variant="block">
        <span data-testid="development-section-pull-request-description">
          <PullRequestDescription {...pr} />
        </span>
      </ActionList.Description>
    </ActionList.LinkItem>
  )
}
