import {CounterLabel} from '@primer/react'
import {number as formatNumber} from '@github-ui/formatters'
import {useCallback, useMemo} from 'react'
import {useCreateBranchMutation} from '../hooks/use-create-branch-mutation'
import type {Repository} from '../types/repository'
import type {PullRequest} from '../types/pull-request'
import pluralize from 'pluralize'
import {
  CreateBranchDialog,
  type BranchNextStep as CreateBranchDialogBranchNextStep,
  type BranchType,
  type OnCreateBranchData,
  type OnCreateBranchOptions,
} from './CreateBranchDialog'

import styles from './CodeScanningCreateBranchDialog.module.css'

export type CodeScanningCreateBranchDialogProps = {
  alertNumbers: number[]
  alertNumbersWithSuggestedFixes: number[]
  firstAlertWithSuggestedFixTitle: string
  repository: Repository
  createPath: string
  branchListCacheKey: string
  onSuccess?: (
    nextStep: BranchNextStep,
    branchName: string | null,
    pullRequest: PullRequest | null,
    errorMessages?: string[],
  ) => void
  onClose: () => void
  someSelectedAlertsAreClosed: boolean
  branchType: BranchType
  returnFocusRef?: React.RefObject<HTMLElement | null>
  isCampaign: boolean
}

export type BranchNextStep = 'none' | CreateBranchDialogBranchNextStep

export const CodeScanningCreateBranchDialog = ({
  alertNumbers,
  alertNumbersWithSuggestedFixes,
  firstAlertWithSuggestedFixTitle,
  repository,
  createPath,
  branchListCacheKey,
  onSuccess: onSuccessProp,
  onClose,
  someSelectedAlertsAreClosed,
  branchType,
  returnFocusRef,
  isCampaign,
}: CodeScanningCreateBranchDialogProps) => {
  const branchTitle = useMemo(() => {
    let prefix: string
    if (isCampaign) {
      prefix = 'campaign-fix'
    } else if (alertNumbersWithSuggestedFixes.length > 0) {
      prefix = 'alert-autofix'
    } else {
      prefix = 'alert-fix'
    }
    return `${prefix}-${alertNumbers.join('-')}`
  }, [isCampaign, alertNumbersWithSuggestedFixes.length, alertNumbers])

  const showCommitMessageField = alertNumbers.length === 1 && alertNumbersWithSuggestedFixes.length === 1

  const defaultCommitMessage = useMemo(() => {
    if (showCommitMessageField) {
      return `Potential fix for code scanning alert no. ${alertNumbersWithSuggestedFixes[0]}: ${firstAlertWithSuggestedFixTitle}`
    }

    return ''
  }, [showCommitMessageField, alertNumbersWithSuggestedFixes, firstAlertWithSuggestedFixTitle])

  const {isPending, error, mutate, data: mutationResponse} = useCreateBranchMutation(createPath)

  const onCreateBranch = useCallback(
    (data: OnCreateBranchData, {onSuccess}: OnCreateBranchOptions) => {
      mutate(
        {
          name: data.branchName,
          alertNumbers,
          commitAutofixSuggestions: alertNumbersWithSuggestedFixes.length > 0,
          createNewBranch: data.createNewBranch,
          createDraftPR: data.createPullRequest,
          commitMessage: data.commitMessage,
          extendedDescription: data.extendedDescription,
        },
        {
          onSuccess: response => {
            onSuccess({
              branchName: response.branchName,
              pullRequest: response.pullRequest,
              errorMessages: response.messages,
            })

            onSuccessProp?.(data.nextStep, response.branchName, response.pullRequest, response.messages)
          },
        },
      )
    },
    [mutate, alertNumbers, alertNumbersWithSuggestedFixes.length, onSuccessProp],
  )

  const dialogTitle = useMemo(() => {
    if (alertNumbersWithSuggestedFixes.length > 0) {
      if (branchType === 'new') {
        return `Commit ${pluralize('autofix', alertNumbersWithSuggestedFixes.length)} to new branch`
      } else {
        return `Commit ${pluralize('autofix', alertNumbersWithSuggestedFixes.length)} to branch`
      }
    } else {
      return 'Create new branch'
    }
  }, [alertNumbersWithSuggestedFixes, branchType])

  const submitButtonContent = useMemo(() => {
    if (alertNumbersWithSuggestedFixes.length > 0) {
      return (
        <>
          Commit {pluralize('change', alertNumbersWithSuggestedFixes.length)}
          {alertNumbersWithSuggestedFixes.length > 1 && (
            <CounterLabel scheme="primary" className={styles.counterLabel}>
              {formatNumber(alertNumbersWithSuggestedFixes.length)}
            </CounterLabel>
          )}
        </>
      )
    } else {
      return 'Create branch'
    }
  }, [alertNumbersWithSuggestedFixes])

  return (
    <CreateBranchDialog
      repository={repository}
      branchListCacheKey={branchListCacheKey}
      branchType={branchType}
      returnFocusRef={returnFocusRef}
      dialogTitle={dialogTitle}
      submitButtonContent={submitButtonContent}
      warningFlashContent={someSelectedAlertsAreClosed && 'Closed and fixed alerts will not be included in this branch'}
      showCommitMessageField={showCommitMessageField}
      showPullRequestNextStep={branchType === 'new' && alertNumbersWithSuggestedFixes.length > 0}
      initialNextStep={branchType === 'existing' || alertNumbersWithSuggestedFixes.length === 0 ? 'local' : 'pr'}
      initialBranchName={branchTitle}
      initialCommitMessage={defaultCommitMessage}
      isPending={isPending}
      error={error}
      createdPullRequest={mutationResponse?.pullRequest}
      onCreateBranch={onCreateBranch}
      onCancel={onClose}
      onClose={onClose}
    />
  )
}
