import {Label, LabelGroup, Stack} from '@primer/react'
import {AlertIcon} from '@primer/octicons-react'
import {
  codeScanningAlertAutofixCommitsPath,
  codeScanningAlertCreateBranchPath,
  codeScanningAlertUpdateAlertLinksPath,
  codeScanningLinkableSearchPath,
  repositoryPath,
} from '@github-ui/paths'
import {SecuritySeverity} from '@github-ui/code-scanning-shared/types/security-severity'
import {RuleSeverity} from '@github-ui/code-scanning-shared/types/rule-severity'
import {CodeScanningAssigneesSection} from '@github-ui/code-scanning-assignees-section/CodeScanningAssigneesSection'
import type {Assignee} from '@github-ui/code-scanning-assignees-section/types'
import {CodeScanningTrackingSection} from '@github-ui/code-scanning-tracking-section/CodeScanningTrackingSection'
import type {TrackingLink} from '@github-ui/code-scanning-shared/types/tracking-link'
import {CodeScanningDevelopmentSection} from '@github-ui/code-scanning-development-section/CodeScanningDevelopmentSection'
import type {BranchData, PullRequestData} from '@github-ui/code-scanning-development-section/types'
import type {AffectedBranch} from '../types/affected-branch'
import {AlertState} from '../types/alert-state'
import type {Repository} from '../types/repository'
import type {RuleTag} from '../types/rule-tag'
import type {SecurityCampaign} from '../types/security-campaign'
import {AffectedBranches} from './AffectedBranches'
import {SeveritySection} from './SeveritySection'
import {AlertMetadata} from '@github-ui/platform-patterns/AlertPageSidebar'
import {CWEItem} from './CWEItem'
import {SecurityCampaigns} from './SecurityCampaigns'
import {RuntimeRisks} from './RuntimeRisks'
import type {RuntimeRisk} from '../types/runtime-risk'

export type CodeScanningAlertSidebarProps = {
  alertNumber: number
  alertTitle: string
  state: AlertState
  repository: Repository
  canWriteAlert: boolean

  // Severity section
  ruleSeverity: RuleSeverity
  securitySeverity: SecuritySeverity | null
  severityFilterUrl: string

  // Assignee section
  currentUser: Assignee
  copilotBot: Assignee | null
  assignees: Assignee[]
  assignableToCopilot: boolean
  hasValidSuggestedFix: boolean
  suggestedFixAliveChannel: string
  useAgenticAutofix: boolean

  // Affected branches section
  affectedBranches: AffectedBranch[] | null
  additionalHiddenBranchesCount: number
  hasAdditionalHiddenBranches: boolean
  staleAlertsDocsUrl: string

  // Tracking section
  trackingSectionEnabled: boolean
  trackingLinks: TrackingLink[]

  // Development section
  hasSuggestedFix: boolean
  pushableByUser: boolean
  branchListCacheKey: string
  linkedBranches: BranchData[]
  linkedPullRequests: PullRequestData[]

  // Security campaigns section
  securityCampaigns: SecurityCampaign[] | null

  // Tags section
  ruleTags: RuleTag[]

  // Weaknesses section
  cweNumbers: number[]

  // Runtime risks section
  runtimeRisks?: RuntimeRisk[]
  runtimeRisksSectionEnabled?: boolean
}

export function CodeScanningAlertSidebar({
  alertNumber,
  alertTitle,
  state,
  canWriteAlert,
  repository,
  ruleSeverity,
  securitySeverity,
  severityFilterUrl,
  currentUser,
  copilotBot,
  assignees,
  assignableToCopilot,
  hasValidSuggestedFix,
  suggestedFixAliveChannel,
  useAgenticAutofix = false,
  affectedBranches,
  additionalHiddenBranchesCount = 0,
  hasAdditionalHiddenBranches = false,
  staleAlertsDocsUrl = '',
  trackingSectionEnabled,
  trackingLinks,
  hasSuggestedFix,
  pushableByUser,
  branchListCacheKey,
  linkedBranches,
  linkedPullRequests,
  securityCampaigns,
  ruleTags,
  cweNumbers,
  runtimeRisks,
  runtimeRisksSectionEnabled,
}: CodeScanningAlertSidebarProps) {
  return (
    <>
      <h2 className="sr-only">Alert metadata</h2>

      <SeveritySection
        ruleSeverity={ruleSeverity}
        securitySeverity={securitySeverity}
        severityFilterUrl={severityFilterUrl}
      />

      <CodeScanningAssigneesSection
        alertNumber={alertNumber}
        repository={repository}
        currentUser={currentUser}
        copilotBot={copilotBot}
        assignees={assignees}
        readonly={!canWriteAlert}
        assignableToCopilot={assignableToCopilot}
        hasValidSuggestedFix={hasValidSuggestedFix}
        suggestedFixAliveChannel={suggestedFixAliveChannel}
        useAgenticAutofix={useAgenticAutofix}
      />

      <AlertMetadata title="Affected branches">
        {affectedBranches ? (
          <>
            {affectedBranches.length === 0 ? (
              <span>{state === AlertState.InPullRequest ? 'Only in Pull Request' : 'None'}</span>
            ) : (
              <AffectedBranches
                affectedBranches={affectedBranches}
                repository={repository}
                additionalHiddenBranchesCount={additionalHiddenBranchesCount}
                hasAdditionalHiddenBranches={hasAdditionalHiddenBranches}
                canWriteAlert={canWriteAlert}
                staleAlertsDocsUrl={staleAlertsDocsUrl}
              />
            )}
          </>
        ) : (
          <Stack align="center" direction="horizontal" gap="condensed">
            <AlertIcon />
            <span>Failed to load branches</span>
          </Stack>
        )}
      </AlertMetadata>

      {trackingSectionEnabled && (
        <CodeScanningTrackingSection
          alertNumber={alertNumber}
          repository={repository}
          readonly={!canWriteAlert}
          alertTrackingLinks={trackingLinks ?? []}
        />
      )}

      <CodeScanningDevelopmentSection
        alertNumber={alertNumber}
        createBranchPath={
          hasSuggestedFix
            ? codeScanningAlertAutofixCommitsPath({
                owner: repository.ownerLogin,
                repo: repository.name,
                alertNumber,
              })
            : codeScanningAlertCreateBranchPath({
                owner: repository.ownerLogin,
                repo: repository.name,
                alertNumber,
              })
        }
        alertTitle={alertTitle}
        hasSuggestedFix={hasSuggestedFix}
        isAlertClosed={state === AlertState.Dismissed || state === AlertState.Fixed}
        linkedBranches={linkedBranches}
        linkedPullRequests={linkedPullRequests}
        pushableByUser={pushableByUser}
        repository={{
          ...repository,
          path: repositoryPath({
            owner: repository.ownerLogin,
            repo: repository.name,
          }),
        }}
        branchListCacheKey={branchListCacheKey}
        updateAlertLinksPath={codeScanningAlertUpdateAlertLinksPath({
          owner: repository.ownerLogin,
          repo: repository.name,
          alertNumber,
        })}
        linkableItemsSearchPath={codeScanningLinkableSearchPath({
          owner: repository.ownerLogin,
          repo: repository.name,
        })}
      />

      {securityCampaigns && (
        <AlertMetadata title="Security campaigns">
          <SecurityCampaigns securityCampaigns={securityCampaigns} repository={repository} />
        </AlertMetadata>
      )}

      {ruleTags.length > 0 && (
        <AlertMetadata title="Tags">
          <LabelGroup>
            {ruleTags.map(tag => (
              <Label variant="secondary" key={tag.name} as="a" href={tag.path}>
                {tag.name}
              </Label>
            ))}
          </LabelGroup>
        </AlertMetadata>
      )}

      {runtimeRisksSectionEnabled && <RuntimeRisks risks={runtimeRisks} />}

      {cweNumbers.length > 0 && (
        <AlertMetadata title="Weaknesses">
          {cweNumbers.map(cwe => (
            <CWEItem key={cwe} cweNumber={cwe} />
          ))}
        </AlertMetadata>
      )}
    </>
  )
}
